`, "",{"version":3,"sources":["webpack://./src/莎历士空间/脚本/身份创建/App.vue"],"names":[],"mappings":"AA4KA,8BACE,UAAW,CACX,gBAAiB,CACjB,iBAAkB,CAClB,cAAe,CACf,mBAAoB,CACpB,YACF,CAEA,2CACE,aACF","sourcesContent":["<template>\n  <div\n    class=\"fixed inset-0 flex items-center justify-center p-4 overflow-y-auto\"\n    :style=\"{ background: 'rgba(6, 4, 10, 0.88)', backdropFilter: 'blur(6px)', zIndex: 999999 }\"\n  >\n    <div\n      class=\"rounded-lg w-full my-6\"\n      :style=\"{\n        maxWidth: '460px',\n        background: 'linear-gradient(160deg, #0c0913, #171122)',\n        border: '1px solid #5c3d7a',\n        boxShadow: '0 0 24px rgba(255, 63, 164, 0.4), 0 0 40px rgba(45, 227, 255, 0.14)',\n        fontFamily: `'Microsoft YaHei', 'PingFang SC', sans-serif`,\n        color: '#f3e9fb',\n      }\"\n    >\n      <div class=\"px-5 pt-5 pb-3 text-center\">\n        <div class=\"text-[13px] tracking-[0.3em]\" style=\"color: #2de3ff\">SALIX SPACE</div>\n        <div class=\"text-[18px] font-bold mt-1\" style=\"color: #f3e9fb\">身份创建</div>\n        <p class=\"text-[12px] mt-2 leading-snug\" style=\"color: #a993c2\">\n          光球在你面前展开全息界面，等待你塑造在莎历士空间中的唯一化身。\n        </p>\n      </div>\n\n      <div class=\"px-5 flex flex-col gap-4 pb-5\">\n        <Field label=\"称呼你的化身\">\n          <input\n            v-model=\"form.昵称\"\n            type=\"text\"\n            placeholder=\"输入一个昵称\"\n            class=\"field-input\"\n            :style=\"fieldStyle\"\n          />\n        </Field>\n\n        <Field label=\"基础种族\">\n          <div class=\"flex gap-2 flex-wrap\">\n            <Choice v-for=\"r in raceOptions\" :key=\"r\" :label=\"r\" :active=\"form.种族 === r\" @click=\"form.种族 = r\" />\n          </div>\n          <input\n            v-if=\"form.种族 === '其他'\"\n            v-model=\"form.种族自定义\"\n            type=\"text\"\n            placeholder=\"描述你想要的种族/形态\"\n            class=\"field-input mt-2\"\n            :style=\"fieldStyle\"\n          />\n        </Field>\n\n        <Field label=\"虚拟形象性别\">\n          <div class=\"flex gap-2 flex-wrap\">\n            <Choice\n              v-for=\"g in genderOptions\"\n              :key=\"g\"\n              :label=\"g\"\n              :active=\"form.性别 === g\"\n              @click=\"form.性别 = g\"\n            />\n          </div>\n        </Field>\n\n        <Field label=\"外观描述（可选）\">\n          <textarea\n            v-model=\"form.外观\"\n            rows=\"3\"\n            placeholder=\"留空则由「守秘者」为你即兴构思\"\n            class=\"field-input resize-none\"\n            :style=\"fieldStyle\"\n          ></textarea>\n        </Field>\n\n        <Field label=\"免费基础改造\">\n          <div class=\"flex flex-col gap-2\">\n            <Choice\n              v-for=\"m in modOptions\"\n              :key=\"m.value\"\n              :label=\"m.label\"\n              :active=\"form.基础改造 === m.value\"\n              full\n              @click=\"form.基础改造 = m.value\"\n            />\n          </div>\n        </Field>\n\n        <button\n          type=\"button\"\n          class=\"mt-1 rounded py-2.5 text-[14px] font-bold tracking-wide transition-transform active:scale-[0.98] disabled:opacity-50\"\n          :style=\"{\n            background: 'linear-gradient(90deg, #ff3fa4, #b366ff)',\n            color: '#0c0913',\n            boxShadow: '0 0 14px rgba(255, 63, 164, 0.5)',\n          }\"\n          :disabled=\"submitting || !canSubmit\"\n          @click=\"submit\"\n        >\n          {{ submitting ? '正在进入莎历士空间…' : '确认身份，进入莎历士空间' }}\n        </button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, reactive, ref } from 'vue';\nimport Choice from './components/Choice.vue';\nimport Field from './components/Field.vue';\n\nconst emit = defineEmits<{ done: [] }>();\n\nconst fieldStyle = {\n  background: '#241a33',\n  border: '1px solid #3d2a52',\n  color: '#f3e9fb',\n};\n\nconst raceOptions = ['人类', '精灵', '恶魔', '其他'];\nconst genderOptions = ['男性', '女性', '双性', '无性', '其他'];\nconst modOptions = [\n  { value: '伪娘化改造（强制/自愿）', label: '伪娘化改造 —— 强制或自愿的性别重塑' },\n  { value: '乳头阴茎', label: '乳头阴茎 —— 胸部的性器官化改造' },\n  { value: '不改造', label: '不改造 —— 获得 3000 额外初始狂乐币' },\n];\n\nconst form = reactive({\n  昵称: '',\n  种族: '人类',\n  种族自定义: '',\n  性别: '女性',\n  外观: '',\n  基础改造: '不改造',\n});\n\nconst submitting = ref(false);\n\nconst canSubmit = computed(() => form.昵称.trim().length > 0 && (form.种族 !== '其他' || form.种族自定义.trim().length > 0));\n\nasync function submit() {\n  if (!canSubmit.value || submitting.value) return;\n  submitting.value = true;\n  try {\n    const mvu_data = Mvu.getMvuData({ type: 'message', message_id: 0 });\n    const 种族形态 = form.种族 === '其他' ? form.种族自定义.trim() : form.种族;\n\n    _.set(mvu_data.stat_data, '主角.昵称', form.昵称.trim());\n    _.set(mvu_data.stat_data, '主角.虚拟形象性别', form.性别);\n    _.set(mvu_data.stat_data, '主角.形象种族形态', 种族形态);\n    _.set(mvu_data.stat_data, '主角.当前形象', form.外观.trim() || '待初始化');\n    _.set(mvu_data.stat_data, '主角.当前状态摘要', '刚完成身份创建，准备进入初始广场');\n\n    if (form.基础改造 === '不改造') {\n      _.set(mvu_data.stat_data, '主角.狂乐币', (mvu_data.stat_data?.主角?.狂乐币 ?? 1000) + 3000);\n    } else {\n      _.set(mvu_data.stat_data, `主角.物化手术记录.${form.基础改造}`, { 状态: '已完成', 进度: 100 });\n    }\n\n    await Mvu.replaceMvuData(mvu_data, { type: 'message', message_id: 0 });\n\n    await generate({\n      user_input: `（身份创建完成：昵称${form.昵称.trim()}，${种族形态}，${form.性别}，${form.基础改造 === '不改造' ? '未接受改造' : '已完成' + form.基础改造}。请描述{{user}}踏入初始广场的第一幕。）`,\n      should_silence: true,\n    });\n\n    emit('done');\n  } catch (error) {\n    console.error('身份创建提交失败', error);\n    toastr.error('生成开场失败，请重试或直接在输入框中继续游玩');\n    submitting.value = false;\n  }\n}\n</script>\n\n<style scoped>\n.field-input {\n  width: 100%;\n  padding: 8px 10px;\n  border-radius: 4px;\n  font-size: 13px;\n  font-family: inherit;\n  outline: none;\n}\n\n.field-input::placeholder {\n  color: #6e5688;\n}\n</style>\n"],"sourceRoot":""}]);
