import { waitUntil } from 'async-wait-until';
import { reloadOnChatChange } from '@util/script';
import App from './App.vue';
let root = null;
function mountOverlay() {
    if (root)
        return;
    root = $('<div id="salix-space-chargen-root"></div>').appendTo('body');
    const app = createApp(App, {
        onDone: () => {
            app.unmount();
            root?.remove();
            root = null;
        },
    });
    app.mount(root[0]);
}
async function init() {
    await waitGlobalInitialized('Mvu');
    await waitUntil(() => _.has(getVariables({ type: 'message', message_id: 0 }), 'stat_data'));
    const mvu_data = Mvu.getMvuData({ type: 'message', message_id: 0 });
    const 昵称 = _.get(mvu_data.stat_data, '主角.昵称');
    if (昵称 === '待初始化' || !昵称) {
        mountOverlay();
    }
}
$(() => {
    errorCatched(init)();
});
reloadOnChatChange();
